import 'dart:async';
import 'dart:convert';
import 'dart:collection';

@pragma('vm:never-inline')
@pragma('vm:entry-point')
void fn0() {

  int numNodes = 6;

  List<List<int>> graph = List.generate(numNodes, (_) => <int>[]);
  graph[5].add(2);
  graph[5].add(0);
  graph[4].add(0);
  graph[4].add(1);
  graph[2].add(3);
  graph[3].add(1);

  List<int> indegree = List.filled(numNodes, 0);
  for (int u = 0; u < numNodes; u++) {
    for (int v in graph[u]) {
      indegree[v]++;
    }
  }

  Queue<int> queue = Queue<int>();
  for (int i = 0; i < numNodes; i++) {
    if (indegree[i] == 0) {
      queue.add(i);
    }
  }

  List<int> topoOrder = <int>[];

  while (queue.isNotEmpty) {
    int u = queue.removeFirst();
    topoOrder.add(u);

    for (int v in graph[u]) {
      indegree[v]--;
      if (indegree[v] == 0) {
        queue.add(v);
      }
    }
  }

  if (topoOrder.length == numNodes) {
    print('Topological Sort: ${topoOrder.join(' ')}');
  } else {
    print('Graph contains a cycle, topological sort not possible.');
  }
}

