List<int> fn0(List<int> requests) {
  if (requests.isEmpty) {
    return <int>[];
  }

  Map<int, int> blockCounts = <int, int>{};
  Set<int> currentBlock = <int>{requests[0]};
  int direction = 0;

  for (int i = 1; i < requests.length; i++) {
    int diff = requests[i] - requests[i - 1];
    int nextDirection = diff == 0 ? direction : (diff > 0 ? 1 : -1);

    if (direction != 0 && nextDirection != direction) {
      for (int floor in currentBlock) {
        blockCounts[floor] = (blockCounts[floor] ?? 0) + 1;
      }
      currentBlock = <int>{};
    }

    currentBlock.add(requests[i]);
    direction = nextDirection;
  }

  for (int floor in currentBlock) {
    blockCounts[floor] = (blockCounts[floor] ?? 0) + 1;
  }

  List<int> result = blockCounts.keys.toList();
  result.sort((a, b) {
    int countCompare = blockCounts[b]!.compareTo(blockCounts[a]!);
    if (countCompare != 0) {
      return countCompare;
    }
    return a.compareTo(b);
  });

  return result;
}

