import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
List<String> fn0(String stream) {
  List<String> result = [];
  int i = 0;

  String bin(int value) {
    if (value < 20) return 'dead';
    if (value < 40) return 'weak';
    if (value < 60) return 'fair';
    if (value < 80) return 'good';
    return 'excellent';
  }

  while (i < stream.length) {
    while (i < stream.length && (stream[i] == ' ' || stream[i] == ';')) {
      i++;
    }

    int start = i;
    while (i < stream.length && RegExp(r'[A-Za-z0-9_]').hasMatch(stream[i])) {
      i++;
    }
    if (start == i || i >= stream.length || stream[i] != '[') {
      i++;
      continue;
    }

    String id = stream.substring(start, i);
    i++;
    int strength = 0;
    String last = '';

    while (i < stream.length && stream[i] != ']') {
      while (i < stream.length && (stream[i] == ' ' || stream[i] == ',')) {
        i++;
      }
      if (i >= stream.length || stream[i] == ']') {
        break;
      }

      String op = stream[i++];

      if (op == '?' || op == '!') {
        String current = op == '!' ? 'lost' : bin(strength);
        if (current != last) {
          result.add('$id:$current');
          last = current;
        }
        if (op == '!') {
          strength = 0;
        }
        continue;
      }

      int numStart = i;
      while (i < stream.length && RegExp(r'[0-9]').hasMatch(stream[i])) {
        i++;
      }
      if (numStart == i) {
        continue;
      }

      int value = int.parse(stream.substring(numStart, i));
      if (op == 'S') {
        strength = value;
      } else if (op == '+') {
        strength += value;
      } else if (op == '-') {
        strength -= value;
      }

      if (strength < 0) {
        strength = 0;
      } else if (strength > 100) {
        strength = 100;
      }
    }

    while (i < stream.length && stream[i] != ';') {
      i++;
    }
  }

  return result;
}

